import sys
sys.path.insert(0, '/workspace/src')
import json
import click
from click.testing import CliRunner
@click.command()
@click.option('--without-xyz', 'enable_xyz', flag_value=False, default=True)
def boolean_cli(enable_xyz):
    click.echo(repr(enable_xyz))
@click.command()
@click.option('--upper', 'mode', flag_value='upper', default=True)
def string_cli(mode):
    click.echo(mode)
rows=[]
for command, argv in ((boolean_cli, []), (boolean_cli, ['--without-xyz']), (string_cli, []), (string_cli, ['--upper'])):
    result=CliRunner().invoke(command, argv)
    rows.append({'exit_code':result.exit_code,'output':result.output})
print(json.dumps(rows, sort_keys=True))
